export const ALL_SRI_LANKA_DISTRICTS = Object.keys(SRI_LANKA_DISTRICTS_AND_TOWNS).sort();

export const getTownsByDistrict = (district) => {
  return SRI_LANKA_DISTRICTS_AND_TOWNS[district] || [];
};

// Flatten all locations with district tag for search
export const ALL_SRI_LANKA_LOCATIONS = ALL_SRI_LANKA_DISTRICTS.reduce((acc, district) => {
  acc.push({ type: 'district', name: district, label: `${district} (District)` });
  const towns = SRI_LANKA_DISTRICTS_AND_TOWNS[district];
  towns.forEach((town) => {
    acc.push({ type: 'town', name: town, district, label: `${town}, ${district}` });
  });
  return acc;
}, []);

